window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-prolapsos-de-orgaos-pelvicos"]={"block":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","label":"Anki · Prolapsos de Órgãos Pélvicos","count":44,"questions":[{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-de323e79b2675fa1","number":"0201k","sourceNumber":"0201k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Comparando-se as queixas clínicas de pacientes com prolapso genital estádio I a IV, pode-se observar que mulheres com estadio:","options":{"A":"I têm mais dificuldade em segurar flatos.","B":"II têm mais obstipação intestinal.","C":"IV têm mais dificuldade em esvaziar a bexiga.","D":"III têm mais perda de urina aos esforços.","E":"I têm mais sangramento por úlcera de decúbito."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231451","ankiGuid":"r)F}t_okS5"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-cca57e6ea4d5011e","number":"0202k","sourceNumber":"0202k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher, 55 anos, relata queixa de “bexiga caída”, que piora com esforço físico e eventual dificuldade de esvaziamento vesical. Ao exame ginecológico, identificamos, segundo a classificação da ICS, o seguinte: ponto Aa + 4; ponto Ba + 4; ponto C − 6; ponto D − 8 CVT 10; ponto Ap 0; ponto Bp 0. O diagnóstico é?","options":{"A":"Prolapso uterino sem alongamento hipertrófico do colo, ausência de distopia de paredes vaginais.","B":"Prolapso uterino com alongamento hipertrófico do colo, sem procidência de parede vaginal anterior e procidência de parede vaginal posterior acentuada.","C":"Ausência de prolapso uterino, presença de alongamento hipertrófico de colo, com distopia acentuada de paredes vaginais anterior e posterior.","D":"Ausência de prolapso uterino e de hipertrofia de colo, presença de procidência moderada de parede vaginal anterior e distopia discreta de parede vaginal posterior."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231452","ankiGuid":"jDFy~9hGAq"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-3480c1446fca355a","number":"0203k","sourceNumber":"0203k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"A paciente que apresenta lesão no diafragma urogenital lesiona os músculos:","options":{"A":"levantadores do ânus e coccígeo","B":"transverso profundo do períneo e coccígeo","C":"transverso profundo e transverso superficial do períneo","D":"levantadores do ânus e transverso superficial do períneo"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231453","ankiGuid":"WECzzh}dU"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-2685f8bad14d9989","number":"0204k","sourceNumber":"0204k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Fisiologicamente, o músculo levantador do ânus normal mantém um estado constante de contração, que provê um soalho sólido capaz de suportar o peso do conteúdo abdominopélvico contra as pressões intra-abdominais.Esta musculatura é uma unidade complexa formada por diversos componentes musculares. Os músculos que compõe o levantador do ânus são:","options":{"A":"pubococcígeo, iliococcígeo e puborretal.","B":"pubococcígeo, transverso superficial do períneo e piriforme.","C":"puborretal, isquiocavernoso, bulbocavernoso.","D":"transverso superficial do períneo, iliococcígeo e bulbocavernoso.","E":"transverso profundo do períneo, isquiocavernoso e puborretal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231454","ankiGuid":"c8aRJ-C&.6"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-16ac3086a40d6d94","number":"0205k","sourceNumber":"0205k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Assinale a alternativa que preenche corretamente as lacunas do parágrafo a seguir: O (A) é a técnica mais utilizada na correção dos prolapsos da parede vaginal anterior e consiste na correção dos defeitos do(a)","options":{"A":"sling autólogo; fáscia endopélvica","B":"reparo paravaginal; elevador do ânus","C":"sacrocolpopexia; fáscia retovaginal","D":"colpoplastia anterior; fáscia pubocervical","E":"colpossuspensão; arco tendíneo da fáscia pélvica"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231455","ankiGuid":"Bwo+=7Ffu["},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-4d3fbc35603b90c1","number":"0206k","sourceNumber":"0206k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente, com 55 anos de idade, vem à consulta relatando como queixa principal sensação de “bola na vagina”. No exame ginecológico, foi constatada a presença de prolapso uterino de grau IV na classificação de Baden-Walker. Com relação à conduta nesse caso, assinale a alternativa correta.","options":{"A":"O uso do estrogênio tópico está indicado nesse caso como terapêutica definitiva.","B":"O procedimento reconstrutivo é a primeira linha de tratamento em relação ao obliterativo.","C":"O tratamento expectante deverá ser priorizado em relação ao procedimento obliterativo.","D":"Após a correção cirúrgica do prolapso, indica-se o uso de estrogênio tópico e exercícios vaginais.","E":"A histerectomia vaginal é o tratamento de eleição para a correção do prolapso quando existe a concomitância de descenso do colo do útero."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231456","ankiGuid":"M52^~liho&"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-a57ef238f6163bae","number":"0207k","sourceNumber":"0207k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"O suporte vaginal foi dividido didaticamente por DeLancey em três níveis. Maria Augusta foi clinicamente diagnosticada com incontinência urinária por hipermobilidade uretral e ruptura perineal. O nível e a correlação das estruturas classificam o caso citado em","options":{"A":"nível I, vagina apical, desinserção dos ligamentos uterossacro e cardinal.","B":"nível I, vagina média, alteração da fusão do terço inferior da vagina com diafragma urogenital e corpo perineal.","C":"nível II, vagina média, desinserção da fáscia endopélvica.","D":"nível III, vagina distal, alteração da fusão do terço inferior da vagina com diafragma urogenital e corpo perineal.","E":"nível III, vagina distal, desinserção dos ligamentos uterossacro e cardinal."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231457","ankiGuid":"t9xr(d:L,i"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-0a7e35248489c03d","number":"0208k","sourceNumber":"0208k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher de 85 anos, com queixa de bola na vagina e dificuldade miccional. Ao exame físico apresenta os seguintes achados segundo a classificação POP-Q: Aa=+3, Bp=+6, C=+7, CVT= 8, CP=3, HG=5, Ap= +3, Bp=+6, D=+5. Hipertensa de difícil controle pressórico e cardiopata. Qual tratamento mais indicado?","options":{"A":"Fisioterapia","B":"Histerectomia vaginal","C":"Pessário vaginal","D":"Colpoplastia anterior e posterior"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231458","ankiGuid":"PA0)sK1&Xc"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-c0175a8c3edad3f5","number":"0209k","sourceNumber":"0209k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Os prolapsos de órgão pélvico é um problema de saúde que afeta milhões de mulheres no mundo, e no final da década de 90 foram quantificado pela sociedade internacional de continência, (POP-Q). Sobre estes prolapsos e POP-Q está correto afirmar:","options":{"A":"As medidas de quantificação dos prolapsos devem ser feitas com paciente em litotomia e no repouso.","B":"Pacientes com o ponto Ba = 0 do POP-Q tem prolapso de vaginal anterior grau II independente do tamanho da vagina.","C":"Uma paciente com medida de D= -9 e C= -6 apresenta uma hipertrofia de colo.","D":"Uma lesão no nível I de sustentação da parede vaginal de acordo com os estudos de DeLancey pode levar há um alargamento do introito e deiscência perineal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231459","ankiGuid":"ga`Q)idD&("},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-5ca23483a51a01df","number":"0210k","sourceNumber":"0210k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Em relação ao assoalho pélvico, assinale a alternativa INCORRETA:","options":{"A":"O diafragma pélvico estende-se transversalmente de forma semelhante a uma rede através da pelve verdadeira, com um hiato central para a uretra, a vagina e o reto e pode ser dividido em dois componentes – os internos e os externos.","B":"O componente externo do diafragma pélvico origina-se do arco tendíneo, estendendo-se do osso pube até a espinha isquiática, que dá origem a fibras de diferentes direções, incluindo o músculo puboccígeo, o músculo iliococígeo e o músculo coccígeo.","C":"O componente interno do diafragma pélvico origina-se do osso pube acima e medialmente das origens do músculo pubococcígeo, porém mais espesso e mais forte.","D":"As fibras superiores do músculo puborretal formam uma alça ao redor do reto até a sínfise púbica e suas fibras inferiores inserem-se na borda inferior do osso púbis de cada lado."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231460","ankiGuid":"EtZJh<vYg7"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-db05a4bbad12b23f","number":"0211k","sourceNumber":"0211k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher de 69 anos vai ao ginecologista com relato de “sensação de peso na vagina” há cerca de cinco anos. A atividade sexual é regular, com frequência quinzenal. É diabética e hipertensa, em uso de glibenclamida e enalapril 5 mg. Informa ter tido cinco gestações a termo, com partos vaginais e 2 abortos. Durante exame ginecológico foi observado prolapso genital. Seguindo a classificação da Sociedade Internacional de Continência (POP-Q), foram anotados os seguintes achados: Legenda: HG: hiato genital; CP: corpo perineal; CVT: comprimento vaginal total; Aa: ponto A da parede anterior; Ba: ponto B da parede anterior; C: ponto C; Ap: ponto A da parede posterior; Bp: ponto B da parede posterior; D: ponto D;\n\nMarque a alternativa que contenha o estadiamento CORRETO do prolapso e o tratamento mais adequado, respectivamente:","options":{"A":"estádio III – colpocleise.","B":"estádio II – colposacrofixação.","C":"estádio III – colporrafia anterior.","D":"estádio II – histerectomia vaginal.","E":"estádio III – histerectomia vaginal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":["question_bank/media/ginecologia-prolapsos-de-orgaos-pelvicos/paste-96beafdb984beae3ea50dced4c133d88fa1fb3ce.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231461","ankiGuid":"Oa,LWOtefo"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-8202fc07246d235d","number":"0212k","sourceNumber":"0212k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"O uso de pessários para o tratamento conservador do prolapso genital feminino tem recebido muita atenção da literatura médica nos últimos anos. Em pacientes com prolapso genital estádios II a III da ICS (International Continence Society) e com intróito vaginal de tamanho normal, o tipo de pessário mais utilizado é:","options":{"A":"Donuts","B":"Gellhorn","C":"Anel","D":"Cubo"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231462","ankiGuid":"dXO_,m=%s/"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-a98b6a3c8f1fba98","number":"0213k","sourceNumber":"0213k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Em relação às estruturas abaixo: I. Músculo pubococcígeo. II. Músculobulbocavernoso. III. Músculo ísquiocavernoso. IV. Músculo transverso superficial do períneo. O chamado Triangulo Urogenital Anterior é composto por:","options":{"A":"I e II.","B":"I e III.","C":"II, III e IV.","D":"I, II e IV."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231463","ankiGuid":"yap<f&}m9H"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-ee1a99eb61995077","number":"0214k","sourceNumber":"0214k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"A colpocleise está indicada para tratamento de prolapso uterino na paciente:","options":{"A":"Que ainda deseja engravidar.","B":"Idosa sem vida sexual ativa.","C":"Com incontinência urinária de esforço associada.","D":"Com hiperatividade do detrusor associada."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231464","ankiGuid":"CVqruCxPZI"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-01180c948bee3b64","number":"0215k","sourceNumber":"0215k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"É considerado fator de risco para prolapso de órgão pélvico:","options":{"A":"Cesariana eletiva","B":"Doença pulmonar obstrutiva","C":"Hipertensão arterial","D":"Diabetes"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231465","ankiGuid":"hvg4|t-9$0"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-b3123107ae9d2c77","number":"0216k","sourceNumber":"0216k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher de 64 anos, G6P6, partos vaginais, procura o ambulatório de ginecologia, por apresentar uma \"bola\" na vagina há um ano. Nega perda involuntária de urina. Hipertensa e diabética, usa inibidor da enzima conversora da angiotensina e metformina. Nega passado cirúrgico. O exame ginecológico é compatível com o sexo e a idade, no entanto apresenta a seguinte avaliação, segundo o POP-q:\n\nQual o provável diagnóstico para essa paciente?","options":{"A":"Prolapso de parede anterior EII","B":"Prolapso de parede posterior EI","C":"Rotura perineal grau 3","D":"Hipertrofia de colo uterino","E":"Polapso apical EIV"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":["question_bank/media/ginecologia-prolapsos-de-orgaos-pelvicos/paste-a795174b880a0b02ad2daf34927ff40cd52d5f30.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231466","ankiGuid":"g2tx$Eh<;x"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-c6626fe098b9a68c","number":"0217k","sourceNumber":"0217k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Os Prolapsos de Órgãos Pélvicos (POP) são um problema de saúde que afeta milhões de mulheres no mundo. Sobre essa patologia está CORRETO afirmar que:","options":{"A":"Não há diferenças de prevalência de POP entre as raças.","B":"A International Continence Society definiu uma classificação dos prolapsos com medidas específicas. Nessa classificação, um prolapso de parede vaginal anterior com medida do ponto Ba = - 2 indicaria um prolapso grau 1.","C":"O prolapso vaginal posterior causa o sintoma de constipação intestinal que indica a correção cirúrgica.","D":"A correlação entre os sintomas e a progressão da classificação do POP é evidente."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231467","ankiGuid":"HL80Bm6?NE"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-9aae0065ef3a6933","number":"0218k","sourceNumber":"0218k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"A colpoplastia com técnica de kelly-kennedy é indicada para:","options":{"A":"Incontinência urinária de esforço;","B":"Retocele;","C":"Cistocele com defeito central;","D":"Prolapso uterino grau I;"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231468","ankiGuid":"b}plXrY-7M"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-c34eca665d4db305","number":"0219k","sourceNumber":"0219k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher, 77 anos, sem vida sexual, apresenta queixa de bola na vagina. Ao exame: POP-Q — Aa +2; Ba +2; C -6; HG 4; CP 4; CVT 8; Ap -2; Bp -2; D ---. Ao teste de esforço com redução do prolapso observa-se perda urinária, sincrônica à tosse. Estudo urodinâmico com redução do prolapso evidenciou pressão de perda de 120 cm H₂O. Qual a melhor conduta?","options":{"A":"Colpocleise e sling retropúbico.","B":"Colpoplastia anterior e sling transobturatório.","C":"Reeducação miccional e fisioterapia do assoalho pélvico.","D":"Colpoplastia anterior e fixação de cúpula em ligamento sacroespinhal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231469","ankiGuid":"cJE$*%p5|%"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-26ad683d7565d232","number":"0220k","sourceNumber":"0220k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Que fatores de risco podem se relacionar à ocorrência de distopias genitais?","options":{"A":"Tabagismo, paridade, história familiar de distopias.","B":"Cirurgias pélvicas prévias, baixo nível sócio econômico, DPOC.","C":"Idade avançada, lacerações perineais pós parto, sedentarismo.","D":"Osteoporose, esclerose múltipla, hipoestrogenismo.","E":"Nenhuma das anteriores."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231470","ankiGuid":"Ec$oFqX`@5"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-61dff9ba16eec390","number":"0221k","sourceNumber":"0221k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Uma senhora de 56 anos, G4A0P4, todos partos vaginais, apresenta constipação há cerca de 30 anos, após o nascimento do primeiro filho, com piora progressiva. Atualmente, consegue evacuar todos os dias porém com necessidade de esforço intenso, chegando a ficar sentada no aparelho sanitário por até uma hora e às vezes necessitando de digitação para remoção das fezes, o que lhe causa grande impacto em qualidade de vida. Já tentou o tratamento com laxativos, fibras alimentares e mudança de hábitos de vida sem sucesso. Já realizou exame de manometria anorretal que foi normal. Qual o diagnóstico mais provável?","options":{"A":"Inércia colônica.","B":"Síndrome do intestino irritável.","C":"Prolapso de parede vaginal posterior (retocele).","D":"Síndrome da contração paradoxal do puborretal (anismo)."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231471","ankiGuid":"tIh*uvs}h:"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-a53974e046387f1a","number":"0222k","sourceNumber":"0222k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"O aumento da expectativa de vida na população em geral permite maior observação de afecções mais prevalentes na faixa etária mais avançada, como os prolapsos de órgãos pélvicos (POP). Apesar de não haver ameaça a vida, é uma causa importante de morbidade. Para auxiliar no diagnóstico, a Sociedade Internacional de Continência (ICS) aprovou o sistema de Quantificação dos Prolapsos de Órgãos Pélvicos (POP-Q), o qual permite avaliar e determinar o tipo e a gravidade dos prolapsos através de pontos pré-determinados, como visto na figura a seguir.\n\nEm relação ao POP-Q, qual a alternativa correta?","options":{"A":"Os pontos são medidos em milímetros e podem ser negativos ou positivos.","B":"Mesmo existindo a presença dos pontos C e D, a avaliação do compartimento apical é facultativa.","C":"Com o advento do POP-Q, não é mais necessário avaliar o órgão genital externo à manobra de Valsalva.","D":"Proporciona padronização das medidas,permitindo, assim, uniformização dos resultados vistos por diferentes observadores.","E":"Pode-se afirmar que é um sistema mais elaborado para auxiliar no diagnóstico preciso dos prolapsos genitais e vem sendo adotado na prática clínica pela maioria dos médicos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":["question_bank/media/ginecologia-prolapsos-de-orgaos-pelvicos/paste-a8af0d49153bc6d9fda39a5aee417ac8c683fba2.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231472","ankiGuid":"Gf&A(n<Bi!"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-d22df86117c05bcb","number":"0223k","sourceNumber":"0223k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher, 52 anos de idade, refere “bola na vagina” há 5 anos e urgeincontinência urinária há 1 ano. Ao exame físico observa-se o seguinte POP-Q: Aa = +3, Ap = +1, Ba = +4, Bp = +1, C = -7, D = -8, HG = 6, CP = 2, CVT = 9. Qual o diagnóstico e a melhor conduta?","options":{"A":"Prolapso vaginal completo, histerectomia vaginal com fixação sacroespinhal da cúpula e anticolinérgico no pós-operatório.","B":"Síndrome da bexiga hiperativa, prescrição de anticolinérgico, e caso não haja melhora indicar colpofixação retropúbica.","C":"Prolapso vaginal do compartimento apical, promontofixação via abdominal e prescrição de B1-adrenérgico.","D":"Prolapso vaginal dos compartimentos anterior e posterior, correção sítio-específica e orientação quanto a possibilidade de regressão dos sintomas urinários no pós- operatório.","E":"Incontinência urinária mista, prescrição de alfa-adrenérgico, e caso não haja melhora indicar correção sítio-específica de parede vaginal anterior."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231473","ankiGuid":"o;8!gG.oe/"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-ab32e5b9cc630db2","number":"0224k","sourceNumber":"0224k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 35 anos, com história de constipação G3P3A0, partos normais, chega ao ambulatório com queixa de bola na vagina. Ao exame físico, apresenta prolapso uterino de estádio II. A paciente refere que deseja ter mais uma gestação, pois se casou novamente e quer ter um filho do novo marido. Assim, a melhor conduta nesse caso é:","options":{"A":"Cirurgia de Manchester;","B":"Colpocleise;","C":"Histerectomia vaginal;","D":"Traquelectomia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231474","ankiGuid":"KQ!32tkCtF"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-d38995213adcb22a","number":"0225k","sourceNumber":"0225k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher de 74 anos, com 4 partos vaginais e queixa de \"bola na vagina\" há 2 anos com piora progressiva e queda da qualidade de vida. No exame físico específico para prolapso genital (POP-Q) observa-se: Aa +3 Ba +6 C +8 HG 4 CP 3 CVT 9 Ap -2 Bp 0 e D +5. Em relação à esta paciente pode-se afirmar que:","options":{"A":"segundo o seu POP-Q a paciente não apresenta prolapso","B":"ela tem um defeito grave no compartimento posterior que pode ser atribuído a lesões na musculatura isqui-púbica","C":"ela tem prolapso nos compartimentos anterior, apical e posterior que são atribuídos às lesões na fáscia pubocervical, nos ligamentos redondos do útero e na fáscia retovaginal, respectivamente.","D":"ela tem prolapso anterior que é atribuído a defeito da fáscia pubocervical e prolapso apical cujo defeito se encontra no complexo uterossacro-cardinal"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231475","ankiGuid":"nmeAAMi^uT"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-6487fcbaa9e627e6","number":"0226k","sourceNumber":"0226k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Os prolapsos de órgãos pélvicos podem levar a uma importante redução da qualidade de vida da mulher. Sobre essa patologia, é correto afirmar:","options":{"A":"É uma importante causa de tratamento cirúrgico pélvico feminino.","B":"Os partos cesáreos ou vaginais, mesmo de repetição, são fatores de risco estatisticamente semelhantes para o desenvolvimento dos prolapsos.","C":"A International Continence Society definiu uma classificação dos prolapsos com medidas específicas; nessa classificação, um prolapso de parede vaginal anterior com medida do ponto Ba = +1 indica um prolapso grau 3.","D":"A bacia óssea tem um papel preponderante na suporte estático e dinâmico dos órgãos pélvicos, e o tecido conjuntivo tem um papel secundário nesse suporte."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231476","ankiGuid":"e}[zM_.2)4"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-c2e3ee357f5d5a8d","number":"0227k","sourceNumber":"0227k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 71 anos, VIIG VP (partos normais) refere bola na vagina há 5 anos, com piora progressiva na sensação de peso e dificuldade para esvaziar a bexiga. De acordo com a classificação de POP-Q, o ponto de maior prolapso é o C, que se situa 2 centímetros para fora do anel himenal. O estádio do prolapso genital e a melhor conduta são, respectivamente:","options":{"A":"Estádio II, sling retropúbico e correção sítio-específica do prolapso.","B":"Estádio III, histerectomia vaginal e correção sítio-específica do prolapso.","C":"Estádio II, sling transobturador e perineoplastia.","D":"Estádio II, correção de prolapso de parede vaginal anterior e posterior","E":"Estádio III, histeropexia e perineoplastia anterior."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231477","ankiGuid":"gL|FY5@pQd"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-28ca8c70d34d799c","number":"0228k","sourceNumber":"0228k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 53 anos de idade vem com queixa de “bexiga caída”, que piora com esforço físico e incontinência urinária aos esforços, com piora progressiva, há 2 anos. Ao exame ginecológico, identificamos o seguinte pela classificação POP-Q (Pelvic Organ Prolapse Quantification system): ponto Aa = +1; ponto Ba = +2; ponto C = -6; ponto D = -8; ponto Ap = -2; ponto Bp = 0. O exame urodinâmico descreve pressão de perda de 40 cm H2O, sem outras anormalidades. O diagnóstico do caso em questão é:","options":{"A":"Ausência de prolapso uterino, com cistocele moderada, retocele discreta e bexiga hiperativa.","B":"Prolapso uterino com alongamento hipertrófico do colo, ausência de cistocele, retocele acentuada e incontinência urinária de esforço por defeito esfincteriano.","C":"Ausência de prolapso uterino, porém com alongamento hipertrófico do colo, distopia acentuada de paredes vaginais e incontinência urinária de esforço sem defeito esfincteriano.","D":"Prolapso uterino, sem alongamento hipertrófico do colo, sem distopias de paredes vaginais e bexiga hiperativa.","E":"Ausência de prolapso uterino, com distopia moderada de paredes vaginais e incontinência urinária de esforço por defeito esfincteriano da uretra."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231478","ankiGuid":"i;[#>-+:^|"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-428cb572f8f2d195","number":"0229k","sourceNumber":"0229k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Com a mudança do estilo de vida nas últimas décadas e com o aumento da preocupação com a fertilidade e função sexual feminina, muitas pacientes com indicação de tratamento cirúrgico para correção de prolapso genital questionam a possibilidade de preservação uterina. São cirurgias para a preservação uterina no prolapso genital: I. Manchester; II. Histeropexia sacroespinhosa; III. Histerossacropexia; IV. Histerectomia vaginal. Estão CORRETAS as afirmações:","options":{"A":"I, somente.","B":"I e II, somente.","C":"I, II e III, somente.","D":"I, II, III e IV."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231479","ankiGuid":"bLN07E*8$R"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-b66f4ae216bbd24d","number":"0230k","sourceNumber":"0230k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 60 anos, casada, com sensação de bola na vagina e dificuldade de esvaziamento vesical. Ao exame, prolapso genital: Aa +3, Ba +6, C +6, HG 5, CP 3, CVT 6, Ap +3, Bp +6, D+6. O diagnóstico, estadiamento e tratamentos mais adequados são:","options":{"A":"Prolapso uterino, procidência de parede vaginal anterior e posterior (estádio IV); histerectomia vaginal, colpofixação sacroespinhosa, colporrafia anterior e colpoperineoplastia.","B":"Prolapso uterino, procidência de parede vaginal anterior e posterior (estádio III) e colporrafia anterior, fixação útero-sacral, colpoperineoplastia","C":"Prolapso de cúpula vaginal, procidência de parede vaginal anterior e posterior (estádio IV) e colpocleise.","D":"Prolapso de cúpula vaginal, procidência de parede vaginal anterior e posterior (estádio III) e colpossacrofixação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231480","ankiGuid":"L~gJFrC2MU"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-96b14b0e180f55d6","number":"0231k","sourceNumber":"0231k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 82 anos de idade, sem vida sexual, com queixa de bola na vagina há mais de 5 anos. Nega outras queixas urogenitais. No exame, observa-se o seguinte estadiamento: POP-Q: Aa = +3; Ba = +5; C = +5; D = +3; Ap = -1; Bp = -1; HG = 3; CP = 2; CVT = 6. Dentre as opções abaixo, assinale a que NÃO será eficaz no tratamento dessa paciente.","options":{"A":"Histerectomia vaginal com colporrafia anterior e posterior.","B":"Colpocleise de Le Fort.","C":"Colpoplastia anterior e posterior com perineorrafia.","D":"Colpocleise parcial."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231481","ankiGuid":"p4P@-z4C`!"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-6f77c1234305a2b3","number":"0232k","sourceNumber":"0232k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Em relação ao tratamento do prolapso dos órgãos pélvicos, afirma-se: I. Os pessários são uma opção para as pacientes com múltiplas comorbidades.; II. Os exercícios de reforço da musculatura do assoalho pélvico estão indicados em prolapsos leves.; III. Os procedimentos de colpocleise são apropriados em pacientes que desejam preservar a função sexual. Está/Estão correta (s) a (s) afirmativa (s):","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e II, apenas.","E":"I, II e III."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231482","ankiGuid":"D@6l..d+1F"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-7e89f7e3aaaac20b","number":"0233k","sourceNumber":"0233k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Na cirurgia do prolapso apical de vagina, pode-se utilizar a via abdominal ou vaginal. As estruturas anatômicas de referência para as técnicas cirúrgicas mais eficazes para a via abdominal ou vaginal são, respectivamente,","options":{"A":"Tórus uterino e pilares da bexiga.","B":"Ligamento redondo e músculo bulbo cavernoso.","C":"Promontório do sacro e ligamento sacro espinhoso.","D":"Aponeurose do reto abdominal e corpo perineal.","E":"Forame obturador e ligamentos de Cooper."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231483","ankiGuid":"m=%P44ZNkJ"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-65ba7e42832dae9b","number":"0234k","sourceNumber":"0234k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"As estruturas, que envolvem a vagina, formam uma rede de fáscias, músculos, ligamentos e complexos neurovasculares, permitindo a adequada posição anatômica desse órgão. Dentre os componentes abaixo, qual é o responsável pela integridade anatômica das paredes laterais da vagina?","options":{"A":"Fáscia endopélvica.","B":"Artéria e nervo pudendo.","C":"Arco tendíneo.","D":"Fáscia retovaginal.","E":"Ligamento cardinal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231484","ankiGuid":"B|3@XF!Qby"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-75595d425948f337","number":"0235k","sourceNumber":"0235k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher, 75 anos, casada, ativa sexualmente, com queixa de sensação de bola e peso na vagina há cerca de 5 anos. Ao exame físico, a quantificação do prolapso de órgãos pélvicos (POP-Q): Aa = +3; Ba = +8; C = +9; HG = 4; CP = 3; CVT = 11; Ap = +3; Bp = +8; D = +9. Qual diagnóstico e tratamento mais recomendados?","options":{"A":"Prolapso de parede vaginal anterior E-III, posterior E-III e uterino E-IV; histerectomia vaginal associada a colpocleise.","B":"Prolapso de parede vaginal anterior E-IV, posterior E-IV e uterino E-IV; histerectomia vaginal associada a colpocleise.","C":"Prolapso de parede vaginal anterior E-IV, posterior E-IV e uterino E-IV; histerectomia vaginal associada a fixação no ligamento uterossacral.","D":"Prolapso de parede vaginal anterior E-III, posterior E-III e uterino E-IV; histerectomia vaginal associada a fixação no ligamento sacro espinhal, colpoplastia anterior e posterior."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231485","ankiGuid":"x;wqHkY+iI"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-5261d694be369b75","number":"0236k","sourceNumber":"0236k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Em relação ao prolapso dos órgãos pélvicos: I. O sistema de sustentação do útero e da vagina é dividido em três níveis, o nível I é o complexo de ligamentos uterossacro / transverso do colo, que mantém o comprimento e o eixo da vagina. II. Os distúrbios mais comuns da sustentação pélvica são retoceles e cistoceles, enteroceles e prolapso uterino, resultante da fraqueza do tecido conjuntivo endopélvico, da sustentação do músculo levantador do ânus ou de ambos. III. As estruturas de sustentação pélvica são: os músculos e os tecidos conjuntivo do assoalho pélvico, o tecido fibromuscular da parede abdominal e o tecido conjuntivo endopélvico. IV. Em geral, a escolha do tratamento depende da intensidade dos sintomas e do grau de prolapso, levando-se em conta a saúde geral e o nível de atividade da paciente. Assinale a alternativa CORRETA:","options":{"A":"Somente as afirmativas I e III estão corretas.","B":"Somente as afirmativas I, II e III estão corretas.","C":"Somente as afirmativas I, II e IV estão corretas.","D":"Somente as afirmativas II, III e IV estão corretas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231486","ankiGuid":"glyrS{_u,G"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-d8e2ce7fdf814430","number":"0238k","sourceNumber":"0238k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 82 anos, com doença de Alzheimer e cardiopatia grave, apresenta prolapso genital: Aa +3; Ba +3; C +7; HG = 6; CP = 3; CVT = 8; Ap +3; Bp +3; DX. O uso do pessário evoluiu com erosão vaginal. O diagnóstico e tratamento mais adequados são:","options":{"A":"Prolapso uterino, procidência de parede vaginal anterior e posterior (estádio IV) e histerectomia vaginal.","B":"Prolapso uterino, procidência de parede vaginal anterior e posterior (estádio III) e colporrafia anterior, fixação uterossacral, colpoperineoplastia.","C":"Prolapso de cúpula, procidência de parede vaginal anterior e posterior e colpocleise.","D":"Prolapso de cúpula, procidência de parede vaginal anterior e posterior e colpossacrofixação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231488","ankiGuid":"fgN|MYvFUn"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-5dc0ac7ffa127a3b","number":"0239k","sourceNumber":"0239k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paula, 60 anos, três partos normais anteriores, vem ao ambulatório de ginecologia com queixa de bola na vagina associada a dor pélvica de moderada intensidade, com piora progressiva nos últimos anos. Ao exame físico, a avaliação de POP-Q (pelvic organ prolapse quantification) mostra os seguintes pontos: Aa = 0, Ba = 0, C = -10, HG = 3, CP = 3, CVT = 12, Ap = - 3, Bp = -3, D =-12. Diante desses valores, assinale a alternativa incorreta.","options":{"A":"Não há prolapso de parede vaginal posterior.","B":"Não há prolapso de parede vaginal apical.","C":"Há prolapso de parede vaginal anterior estadio II.","D":"Há rotura perineal.","E":"Não há sinais de hipertrofia de colo uterino."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231489","ankiGuid":"Md{.UlQ<{."},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-ca8f73a0775bb818","number":"0240k","sourceNumber":"0240k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Prolapso de órgão pélvico (POP) é um problema de saúde que afeta milhões de mulheres em todo o mundo. Sua etiologia é muito fatorial e tende a se desenvolver ao longo dos anos. Sobre esta patologia, assinale a alternativa correta:","options":{"A":"São fatores de risco associados a prolapso de órgãos pélvicos: nuliparidade, obesidade, constipação, fatores genéticos e espinha bífida.","B":"Procedimentos cirúrgicos obliterativos têm taxa de sucesso superior em comparação aos reconstrutivos e devem ser realizados em mulheres com desejo de atividade sexual futura.","C":"Procedimentos cirúrgicos reconstrutivos têm como objetivo restaurar a anatomia pélvica e a abordagem cirúrgica poderá ser somente por via vaginal.","D":"O Sistema de Quantificação de Prolapso de Órgão Pélvico é um avanço no estudo do prolapso permitindo aos pesquisadores relatarem os achados de forma padronizada.","E":"Para o caso acima citado a cirurgia de colporrafia posterior visa principalmente reconstruir a camada fibromuscular entre a bexiga e a vagina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231490","ankiGuid":"c3[-h;n`[m"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-d65ac7584784bba2","number":"0241k","sourceNumber":"0241k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"No tratamento do prolapso genital, a colpocleise:","options":{"A":"Está proscrita no tratamento moderno do prolapso.","B":"Pode revelar uma incontinência urinária oculta.","C":"Tem taxa de sucesso inferior a 50 % na maioria dos estudos.","D":"Apresenta taxas de complicações semelhantes aos procedimentos reconstrutivos.","E":"Não afeta a função sexual da paciente."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231491","ankiGuid":"c&[(ep|?Xl"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-34810ce03a066023","number":"0242k","sourceNumber":"0242k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher de 77 anos de idade refere desconforto vaginal há 10 anos que vem piorando progressivamente. É G3P3 (normais), menopausa aos 50 anos; nunca usou terapia hormonal, não refere cirurgias anteriores. No exame físico, observa-se mucosa vaginal pálida, com áreas escoriadas. A avaliação do prolapso genital mostrou o seguinte: (VER IMAGEM)\n\nA paciente tem indicação de:","options":{"A":"Estrogênio tópico local.","B":"Correção cirúrgica do prolapso de parede vaginal anterior.","C":"Histerectomia vaginal com encurtamento de paramétrios.","D":"Avaliação urodinâmica com correção do prolapso antes de indicar o tratamento.","E":"Antimicrobiano em forma de creme tópico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":["question_bank/media/ginecologia-prolapsos-de-orgaos-pelvicos/paste-99cd069427d4ee34750bff864b91bb29d956d4e2.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231492","ankiGuid":"dzyEP0n^Zz"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-968c612666df405e","number":"0243k","sourceNumber":"0243k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Mulher branca, 46 anos, G = III, P = III, procurou o serviço de ginecologia com queixa de “bola” na vagina. O exame ginecológico mostrou colo uterino, após ser pinçado e tracionado, ultrapassando a fúrcula vulvar. O tratamento cirúrgico indicado de acordo com a classificação de Baden- Walker foi para:","options":{"A":"Prolapso uterino de 1º grau.","B":"Retocistocele.","C":"Prolapso uterino de 2º grau.","D":"Prolapso uterino de 3º grau."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231493","ankiGuid":"b7V`J{~>Z@"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-a20379ab6a8f37fa","number":"0244k","sourceNumber":"0244k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"A principal etiologia do prolapso uterino em pacientes nulíparas é:","options":{"A":"Lesão iatrogênica do paramétrio.","B":"Fatores constitucionais.","C":"Mioma uterino em parturição.","D":"Retroversão uterina congênita.","E":"Uso de esteroides anabolizantes."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231494","ankiGuid":"rm}{oQ:i85"},{"id":"anki-ginecologia-prolapsos-de-orgaos-pelvicos-c2a465e0401301ee","number":"0245k","sourceNumber":"0245k","collectionBlock":"anki:ginecologia-prolapsos-de-orgaos-pelvicos","collectionLabel":"Anki · Prolapsos de Órgãos Pélvicos","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Prolapsos de Órgãos Pélvicos","subtopic":"","stem":"Paciente de 34 anos, gesta 4 para 4, chegou ao ambulatório de ginecologia com queixa de “bola” na vagina. Ao exame, foi observado prolapso de parede vaginal anterior. Considerando a etiologia, assinale a alternativa CORRETA:","options":{"A":"Defeito da membrana perineal.","B":"Defeito do centro tendíneo do períneo.","C":"Defeito do arco tendíneo da fáscia pélvica.","D":"Defeitos dos paramétrios e ligamentos uterossacros.","E":"Defeito da fáscia retovaginal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Prolapsos de Órgãos Pélvicos","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Prolapsos de Órgãos Pélvicos","Anki"],"ankiNoteId":"1780578231495","ankiGuid":"lyHq;i8%4"}]};
